    need(hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()==spec["git_blob_sha"],"factory Git identity")
    pieces=[];records=[]
    for method in spec["methods"]:
        original=java_block(raw,method["signature"]);original_bytes=original.encode("utf-8")
        need(len(original_bytes)==method["bytes"] and sha(original_bytes)==method["sha256"],"original factory method pin")
        projected=original;applied=[]
        for patch in spec["replacements"]:
            if patch["signature"]==method["signature"]:
                need(projected.count(patch["before"])==patch["count"]==1,"unique explicit fixture adapter")
                projected=projected.replace(patch["before"],patch["after"])
                applied.append(patch)
        restored=projected
        for patch in reversed(applied):
            need(restored.count(patch["after"])==1,"unique reverse fixture adapter")
            restored=restored.replace(patch["after"],patch["before"])
        need(restored==original,"factory method must reverse to the exact original")
